[MITM]
hostname = www.nfmovies.com

[Rewrite]
request if ${url} ~= /^https?:\/\/www\.nfmovies\.com\/pic\/tu\//i then reject_img(200)
request if ${url} ~= /^https?:\/\/www\.nfmovies\.com\/templets\/default\/images\/logos/i then reject_img(200)
request if ${url} ~= /^https?:\/\/www\.nfmovies\.com\/uploads\/images\/play\.jpg/i then reject_img(200)
